template:
% 参数由系统自动注入；圆内接四边形：四顶点在同一圆上，外接圆实线
% 视觉归一化：外接圆直径缩放到 6 个坐标单位，线宽字体不缩放；顶点标签放圆外
\pgfmathsetmacro{\figscale}{3 / \r}
\pgfmathsetmacro{\lab}{\r + 0.45/\figscale}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  % 外接圆
  \draw[thick] (0,0) circle [radius=\r];
  % 四个顶点按圆心角逆时针放置
  \coordinate (A) at (\anga:\r);
  \coordinate (B) at (\angb:\r);
  \coordinate (C) at (\angc:\r);
  \coordinate (D) at (\angd:\r);
  \draw[thick] (A) -- (B) -- (C) -- (D) -- cycle;
  % 对角线 AC
  \ifnum\showdiagac>0
    \draw[thick] (A) -- (C);
  \fi
  % 对角线 BD
  \ifnum\showdiagbd>0
    \draw[thick] (B) -- (D);
  \fi
  % 圆心 O
  \ifnum\showcenter>0
    \fill (0,0) circle [radius=1.6pt];
    \node[below=3pt] at (0,0) {$O$};
  \fi
  % 顶点标签（圆外沿半径方向）
  \node at (\anga:\lab) {$A$};
  \node at (\angb:\lab) {$B$};
  \node at (\angc:\lab) {$C$};
  \node at (\angd:\lab) {$D$};
\end{tikzpicture}
